package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class DownloadPlaylistTest {
 @Test public void acceptsMixAndVideoWithPlaylist(){assertEquals("https://www.youtube.com/playlist?list=RDqHZiIxprsrs",DownloadLinks.resolve("https://youtube.com/playlist?list=RDqHZiIxprsrs&playnext=1&si=xyz"));assertTrue(DownloadLinks.isPlaylist(DownloadLinks.resolve("https://www.youtube.com/watch?v=qHZiIxprsrs&list=RDqHZiIxprsrs")));assertFalse(DownloadLinks.isPlaylist(DownloadLinks.resolve("https://youtu.be/qHZiIxprsrs")));}
 @Test public void rejectsSpoofedHost(){for(String u:new String[]{"https://youtube.com.evil.test/playlist?list=RDqHZiIxprsrs","https://youtube.com@evil.test/playlist?list=RDqHZiIxprsrs","file:///playlist?list=RDqHZiIxprsrs","https://youtube.com/playlist?list=RDqHZiIxprsrs&list=RDqHZiIxprsrs"})try{DownloadLinks.resolve(u);fail(u);}catch(IllegalArgumentException expected){}}
 @Test public void validatesQueue()throws Exception{List<YoutubeDownloads.Entry> entries=Arrays.asList(new YoutubeDownloads.Entry("A","https://youtu.be/aqz-KE-bpKQ"),new YoutubeDownloads.Entry("B","https://youtu.be/qHZiIxprsrs"));assertEquals(2,DownloadQueue.validate(DownloadQueue.encode(entries)).length());try{DownloadQueue.encode(Arrays.asList(entries.get(0),entries.get(0)));fail();}catch(Exception expected){}try{DownloadQueue.validate("[]");fail();}catch(Exception expected){}}
 @Test public void batchSelectsMp3AndBestVideoWithAudio()throws Exception{YoutubeDownloads.Option a=new YoutubeDownloads.Option("Áudio MP3 • 192 kbps","a",null,"mp3","audio/mpeg"),v1=new YoutubeDownloads.Option("Vídeo MP4 • 1080p","v","a","mp4","video/mp4"),v2=new YoutubeDownloads.Option("Vídeo MP4 • 720p","v","a","mp4","video/mp4"),v3=new YoutubeDownloads.Option("Vídeo MP4 • 360p","v",null,"mp4","video/mp4");YoutubeDownloads.Result r=new YoutubeDownloads.Result("Title",Arrays.asList(a,v1,v2,v3));assertSame(a,YoutubeDownloads.choose(r,"mp3"));assertSame(v1,YoutubeDownloads.choose(r,"mp4"));}
 @Test public void usesLowestCombinedVideoForRequestedAudioWithoutChangingFormat()throws Exception{YoutubeDownloads.Option hd=new YoutubeDownloads.Option("Vídeo MP4 • 720p • com som","hd",null,"mp4","video/mp4",false,"",true),low=new YoutubeDownloads.Option("Vídeo MP4 • 144p • com som","low",null,"mp4","video/mp4",false,"",true);YoutubeDownloads.Result result=new YoutubeDownloads.Result("No separate audio",Arrays.asList(hd,low));for(String format:Arrays.asList("mp3","m4a","aac")){YoutubeDownloads.Option chosen=YoutubeDownloads.choose(result,format);assertEquals("low",chosen.first);assertEquals(format,chosen.extension);assertFalse(chosen.original);assertNull(chosen.second);}YoutubeDownloads.Option separate=new YoutubeDownloads.Option("Áudio MP3","audio",null,"mp3","audio/mpeg");assertSame(separate,YoutubeDownloads.choose(new YoutubeDownloads.Result("Separate available",Arrays.asList(low,separate)),"mp3"));}
 @Test public void neverTreatsSilentVideoAsAudioAndExplainsUnavailableSelection()throws Exception{YoutubeDownloads.Option silent=new YoutubeDownloads.Option("Vídeo MP4 • 1080p • juntar áudio","video",null,"mp4","video/mp4");YoutubeDownloads.Result result=new YoutubeDownloads.Result("Silent",Collections.singletonList(silent));for(String format:Arrays.asList("mp3","mp4"))try{YoutubeDownloads.choose(result,format);fail();}catch(Exception expected){assertTrue(expected.getMessage(),expected.getMessage().contains(format.toUpperCase(Locale.ROOT)));assertTrue(expected.getMessage(),expected.getMessage().contains("1080p"));assertTrue(expected.getMessage(),expected.getMessage().contains("link individual"));}}
 @Test public void selectionAndQueueGrowPastOldCapsWithoutLosingMarks()throws Exception{List<YoutubeDownloads.Entry> entries=new ArrayList<>();for(int i=0;i<1200;i++)entries.add(new YoutubeDownloads.Entry("Vídeo "+i,"https://www.youtube.com/watch?v="+String.format(Locale.ROOT,"%011d",i)));PlaylistSelection first=new PlaylistSelection(entries.subList(0,50));first.all(true);PlaylistSelection expanded=first.expanded(entries);assertEquals(50,expanded.count());assertFalse(expanded.contains(1000));expanded.all(true);String json=DownloadQueue.encode(expanded.chosen());assertTrue(json.length()>64000);assertEquals(1200,DownloadQueue.validate(json).length());assertEquals(1200,PlaylistSelection.decode(expanded.encode()).count());BatchDownloads.Summary summary=BatchDownloads.run(1200,i->{},(i,ok)->{},()->{});assertEquals(1200,summary.success);assertFalse(summary.stopped);}
 @Test public void paginationCursorRoundTripsWithoutLosingContinuationBody()throws Exception{List<YoutubeDownloads.Entry> items=Collections.singletonList(new YoutubeDownloads.Entry("A","https://youtu.be/aqz-KE-bpKQ"));org.schabi.newpipe.extractor.Page page=new org.schabi.newpipe.extractor.Page("https://www.youtube.com/youtubei/v1/browse","continuation",Arrays.asList("one","two"),Collections.singletonMap("key","value"),new byte[]{1,2,3});YoutubeDownloads.Playlist original=new YoutubeDownloads.Playlist("List","https://www.youtube.com/playlist?list=PLabcdefghijk",items,page),restored=YoutubeDownloads.restore(YoutubeDownloads.cursor(original),original.title,items);assertTrue(restored.limited);assertEquals(original.url,restored.url);assertEquals(page.getUrl(),restored.next.getUrl());assertEquals(page.getIds(),restored.next.getIds());assertEquals(page.getCookies(),restored.next.getCookies());assertArrayEquals(page.getBody(),restored.next.getBody());}
}
